"use client"

import * as React from "react"
import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"

// Base UI's Root renders a <span>, so disabled styling hangs off data-disabled
// instead of the :disabled pseudo-class.

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Switch = React.forwardRef<
  HTMLSpanElement,
  WithClassName<SwitchPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <SwitchPrimitive.Root
    ref={ref}
    className={cn(
      "group/switch peer inline-flex h-[1.375rem] w-[2.375rem] shrink-0 cursor-pointer items-center rounded-full",
      // Unchecked: recessed well pressed into the surface
      "bg-input [box-shadow:var(--shadow-inset)]",
      "transition-[background,box-shadow] duration-fast",
      "focus-visible:outline-none focus-visible:[box-shadow:var(--shadow-inset),0_0_0_0.125rem_oklch(1_0_0_/_0.2)]",
      "data-disabled:cursor-not-allowed data-disabled:opacity-50",
      // Checked: reuse the primary button material (pill gradient + raised pill shadow)
      "data-checked:bg-[image:var(--pill-gradient)]",
      "data-checked:[box-shadow:var(--shadow-pill)]",
      className
    )}
    {...props}
  >
    <SwitchPrimitive.Thumb
      className={cn(
        "pointer-events-none block h-[1.125rem] w-[1.125rem] rounded-full bg-foreground",
        "[box-shadow:0_0_0_0.03125rem_oklch(0_0_0_/_0.25),0_0.0625rem_0.125rem_oklch(0_0_0_/_0.4)]",
        "data-checked:translate-x-[1.125rem]",
        "data-unchecked:translate-x-0.5",
        "origin-left data-checked:origin-right rtl:origin-right rtl:data-checked:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none"
      )}
    />
  </SwitchPrimitive.Root>
))
Switch.displayName = "Switch"

export { Switch }
